(()=>{'use strict';
const $=id=>document.getElementById(id),form=$('certificateForm');
const companyDefault='Die neXus Procurement GmbH ist eine Unternehmensberatung mit Schwerpunkt auf dem indirekten Einkauf. Sie unterstützt Unternehmen bei strategischen und operativen Einkaufsaufgaben und begleitet die Weiterentwicklung von Einkaufsorganisationen und -prozessen. Ergänzend bietet neXus Trainings und Workshops für Einkaufsteams an.';
const areaDefault='strategischer und operativer Einkauf';
function defaultDuties(interim){return interim?'Zu den Tätigkeitsschwerpunkten gehören die Analyse von Einkaufsstrukturen, Prozessen, Bedarfen und relevanten Daten sowie die Ableitung von Verbesserungspotenzialen. Das Aufgabenfeld umfasst die Mitwirkung an Konzepten zur Weiterentwicklung von Einkaufsprozessen und Beschaffungsstrategien sowie die Begleitung von Ausschreibungen, Lieferantenanalysen und Verhandlungen. Die Abstimmung mit Kundinnen und Kunden sowie Projektbeteiligten, die Aufbereitung von Ergebnissen und Entscheidungsvorlagen und die Unterstützung bei Workshops ergänzen die Tätigkeit.':'Zu den Tätigkeitsschwerpunkten gehörten die Analyse von Einkaufsstrukturen, Prozessen, Bedarfen und relevanten Daten sowie die Ableitung von Verbesserungspotenzialen. Das Aufgabenfeld umfasste die Mitwirkung an Konzepten zur Weiterentwicklung von Einkaufsprozessen und Beschaffungsstrategien sowie die Begleitung von Ausschreibungen, Lieferantenanalysen und Verhandlungen. Die Abstimmung mit Kundinnen und Kunden sowie Projektbeteiligten, die Aufbereitung von Ergebnissen und Entscheidungsvorlagen und die Unterstützung bei Workshops ergänzten die Tätigkeit.';}
const gradeNames=['Sehr gut','Gut','Befriedigend','Ausreichend'];
const categories=[['knowledge','Fachwissen'],['analysis','Auffassungsgabe und Analyse'],['initiative','Eigeninitiative und Engagement'],['resilience','Belastbarkeit'],['method','Arbeitsweise'],['results','Arbeitsergebnisse'],['overall','Gesamtbewertung'],['conduct','Sozialverhalten']];
categories.forEach(([id,name])=>{const label=document.createElement('label');label.textContent=name;const select=document.createElement('select');select.id='grade_'+id;gradeNames.forEach((name,i)=>select.add(new Option((i+1)+' – '+name,String(i+1))));select.value='2';label.append(select);$('gradeFields').append(label);});
const ids=['kind','salutation','firstName','lastName','street','postcode','city','birth','position','start','end','area','duties','company','reason','customReason','issuePlace','issueDate','signName','signRole',...categories.map(([id])=>'grade_'+id)];
const value=id=>$(id).value.trim(),fallback=(id,label)=>value(id)||'['+label+']';
const date=id=>{const v=value(id);if(!v)return '[Datum]';const [y,m,d]=v.split('-');return d+'.'+m+'.'+y;};
const grade=id=>Number($('grade_'+id).value)-1;
const text=(tag,content,cls)=>{const el=document.createElement(tag);el.textContent=content;if(cls)el.className=cls;return el;};
let previousInterim=false;
$('area').value=areaDefault;$('duties').value=defaultDuties(false);$('company').value=companyDefault;
const now=new Date();$('issueDate').value=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');
function render(){
 const interim=value('kind')==='interim',person=value('salutation')+' '+fallback('lastName','Nachname'),full=value('salutation')+' '+fallback('firstName','Vorname')+' '+fallback('lastName','Nachname');
 if(interim!==previousInterim&&value('duties')===defaultDuties(previousInterim))$('duties').value=defaultDuties(interim);
 previousInterim=interim;$('endField').hidden=interim;$('end').required=!interim;$('reasonField').hidden=interim;$('interimHint').hidden=!interim;$('customReasonField').hidden=interim||value('reason')!=='custom';$('customReason').required=!interim&&value('reason')==='custom';
 const root=$('certificatePreview');root.replaceChildren();const logo=new Image();logo.src='../nexus-logo.png';logo.alt='neXus Procurement';logo.className='certificate-logo';const head=document.createElement('div');head.className='letterhead';const details=document.createElement('div');details.className='letterhead-company';details.append(text('strong','neXus Procurement GmbH'),text('div','Am Heineshof 29'),text('div','41066 Mönchengladbach'),text('div','www.nexus-procurement.com'));head.append(details,logo);root.append(head,text('div','neXus Procurement GmbH · Am Heineshof 29 · 41066 Mönchengladbach','sender-line'));
 root.append(text('address',[full,value('street'),[value('postcode'),value('city')].filter(Boolean).join(' ')].filter(Boolean).join('\n')));
 root.append(text('h1',interim?'Zwischenzeugnis':'Arbeitszeugnis'));
 const birth=value('birth')?', geboren am '+date('birth')+',':'';
 root.append(text('p',full+birth+' '+(interim?'ist seit dem '+date('start'):'war vom '+date('start')+' bis zum '+date('end'))+' als '+fallback('position','Position')+' bei der neXus Procurement GmbH tätig.'));
 if(value('company'))root.append(text('p',value('company')));
 root.append(text('p',person+' '+(interim?'ist':'war')+' im Einsatzbereich '+fallback('area','Einsatzbereich')+' tätig.'));
 root.append(text('p',fallback('duties','Tätigkeitsbeschreibung')));
 const past=interim?'sind':'waren',single=interim?'ist':'war';
 root.append(text('p','Die Fachkenntnisse '+past+' '+['stets außerordentlich umfassend und sicher.','stets umfassend und sicher.','umfassend und sicher.','für die übertragenen Aufgaben ausreichend.'][grade('knowledge')]+' Die Auffassungsgabe und Analysefähigkeit '+single+' '+['stets sehr gut.','stets gut.','gut.','ausreichend.'][grade('analysis')]));
 root.append(text('p','Die Eigeninitiative und das Engagement '+past+' '+['stets außerordentlich hoch.','stets hoch.','hoch.','den Anforderungen entsprechend.'][grade('initiative')]+' Die Belastbarkeit '+single+' '+['auch bei besonders hoher Belastung stets sehr gut.','auch bei hoher Belastung stets gut.','bei üblicher Belastung gut.','den Anforderungen entsprechend.'][grade('resilience')]+' Die Arbeitsweise '+single+' '+['stets besonders strukturiert, äußerst sorgfältig und selbstständig.','stets strukturiert, sorgfältig und selbstständig.','strukturiert, sorgfältig und selbstständig.','insgesamt zweckmäßig und sorgfältig.'][grade('method')]));
 root.append(text('p','Die Arbeitsergebnisse '+past+' '+['stets sehr gut.','stets gut.','gut.','insgesamt zufriedenstellend.'][grade('results')]+' Die übertragenen Aufgaben '+(interim?'erfüllt':'erfüllte')+' '+person+' '+['stets zu unserer vollsten Zufriedenheit.','stets zu unserer vollen Zufriedenheit.','zu unserer vollen Zufriedenheit.','zu unserer Zufriedenheit.'][grade('overall')]));
 root.append(text('p','Das Verhalten gegenüber Vorgesetzten, Kolleginnen und Kollegen sowie Kundinnen und Kunden '+single+' '+['stets vorbildlich.','stets einwandfrei.','einwandfrei.','insgesamt korrekt.'][grade('conduct')]));
 if(interim){root.append(text('p','Dieses Zwischenzeugnis wird auf eigenen Wunsch von '+(value('salutation')==='Herr'?'Herrn ':'Frau ')+fallback('lastName','Nachname')+' erstellt. Wir danken für die bisher geleistete Arbeit und freuen uns auf die weitere Zusammenarbeit.'));}
 else{const reasons={none:person+' verlässt unser Unternehmen zum '+date('end')+'.',own:person+' verlässt unser Unternehmen zum '+date('end')+' auf eigenen Wunsch.',probation:'Das Arbeitsverhältnis mit '+person+' endet zum '+date('end')+' mit Ablauf der Probezeit.',fixed:'Das befristete Arbeitsverhältnis mit '+person+' endet zum '+date('end')+' durch Ablauf der vereinbarten Befristung.',agreement:'Das Arbeitsverhältnis mit '+person+' endet zum '+date('end')+' im gegenseitigen Einvernehmen.',custom:value('customReason')||'[Eigene Schlussformulierung]'};root.append(text('p',reasons[value('reason')]+' Wir danken für die geleistete Arbeit und wünschen für die berufliche und persönliche Zukunft alles Gute.'));}
 root.append(text('p',fallback('issuePlace','Ort')+', '+date('issueDate')));
 const sign=document.createElement('div');sign.className='signature';sign.append(text('p','____________________________'),text('p',fallback('signName','Name der unterzeichnenden Person')),text('p',fallback('signRole','Funktion')));root.append(sign);
 root.append(text('footer','neXus Procurement GmbH | Am Heineshof 29 | 41066 Mönchengladbach\nwww.nexus-procurement.com | Sitz der Gesellschaft: Mönchengladbach | AG Mönchengladbach: HRB 22810'));
}
function validate(){form.classList.add('was-validated');if(!form.checkValidity()){form.reportValidity();$('certificateStatus').textContent='Bitte alle Pflichtfelder vollständig ausfüllen.';return false;}if(value('kind')==='final'&&value('end')<value('start')){$('certificateStatus').textContent='Das Austrittsdatum darf nicht vor dem Eintrittsdatum liegen.';$('end').focus();return false;}if(value('birth')&&value('birth')>=value('start')){$('certificateStatus').textContent='Bitte Geburtsdatum und Eintrittsdatum prüfen.';return false;}if(value('issueDate')<value('start')){$('certificateStatus').textContent='Das Zeugnisdatum darf nicht vor dem Eintritt liegen.';return false;}$('certificateStatus').textContent='';return true;}
const edit=()=>{$('certificateStatus').textContent='';render();};form.addEventListener('input',edit);form.addEventListener('change',edit);form.addEventListener('submit',e=>e.preventDefault());
$('resetDuties').onclick=()=>{if(!confirm('Eigene Änderungen an Einsatzbereich und Aufgaben durch den Standardtext ersetzen?'))return;$('area').value=areaDefault;$('duties').value=defaultDuties(value('kind')==='interim');render();};
document.addEventListener('click',e=>{if(e.target.closest('#certificatePrint')){render();if(!validate()){e.preventDefault();e.stopImmediatePropagation();}}},true);
$('certificateSave').onclick=()=>{const data={format:'nexus-zeugnis',version:1,values:Object.fromEntries(ids.map(id=>[id,$(id).value]))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='neXus_Zeugnis.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),15000);$('certificateStatus').textContent='JSON-Sicherung bereitgestellt.';};
$('certificateLoad').onclick=()=>$('certificateFile').click();
$('certificateFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const data=JSON.parse(await f.text());if(data.format!=='nexus-zeugnis'||data.version!==1||!data.values||ids.some(id=>typeof data.values[id]!=='string'))throw Error('Bitte eine JSON-Sicherung des neXus Zeugnisgenerators auswählen.');for(const id of ids){const el=$(id),v=data.values[id];if(el.tagName==='SELECT'&&![...el.options].some(o=>o.value===v))throw Error('Ungültige Auswahl in der Sicherung.');if(el.type==='date'&&v&&!/^\d{4}-\d{2}-\d{2}$/.test(v))throw Error('Ungültiges Datum in der Sicherung.');}ids.forEach(id=>$(id).value=data.values[id]);previousInterim=value('kind')==='interim';render();$('certificateStatus').textContent='Zeugnisentwurf importiert.';}catch(err){$('certificateStatus').textContent='Import nicht möglich: '+err.message;}finally{e.target.value='';}};
render();
})();
